<div class="card">@forelse($conversation->messages as $message)<article><h2>{{ ['user'=>'Usuario','assistant'=>'IA','human'=>'Humano'][$message->role->value] }}</h2>@if($message->status->value==='completed')<p>{{ $message->content }}</p>@elseif($message->status->value==='failed')<p>No fue posible generar la respuesta.</p>@else<p>Generando respuesta…</p>@endif @if($message->role->value==='assistant'&&$message->status->value==='completed')<p><strong>Confianza:</strong> {{ ['high'=>'Alta','medium'=>'Media','low'=>'Baja'][$message->confidence] }}</p><p><strong>Intervención humana:</strong> {{ $message->needs_handoff?'Sí':'No' }}</p>@if($message->needs_handoff)<p>{{ ['insufficient_knowledge'=>'Información insuficiente','low_confidence'=>'Confianza baja','human_requested'=>'Solicitada por la persona','sensitive_action'=>'Acción sensible','policy_restriction'=>'Restricción de política'][$message->handoff_reason]??'Revisión humana requerida' }}</p>@endif @if($message->citations->isNotEmpty())<h3>Fuentes</h3><ol>@foreach($message->citations as $citation)<li><strong>{{ $citation->label }} · {{ $citation->chunk->source->name }}</strong> — {{ ($citation->chunk->locator['kind']??null)==='faq'?'Pregunta frecuente '.($citation->chunk->locator['faq_number']??''):'Sección '.($citation->chunk->locator['section']??'') }}, parte {{ $citation->chunk->locator['part']??1 }}</li>@endforeach</ol>@endif @endif</article>@empty<p>Envía el primer mensaje para comenzar.</p>@endforelse</div>
@if($conversation->actionRuns->isNotEmpty())<div class="card"><h2>Acciones solicitadas</h2>@foreach($conversation->actionRuns as $action)<p><a href="{{ route('tenant.admin.ai-actions.show',$action) }}">{{ app(\App\Domain\AI\Actions\ActionRegistry::class)->find($action->action_key)?->displayName ?? 'Acción no disponible' }}</a> · {{ ['requested'=>'Solicitada','awaiting_confirmation'=>'Requiere confirmación','executing'=>'En ejecución','succeeded'=>'Completada','failed'=>'No completada'][$action->status->value] }}</p>@endforeach</div>@endif
@if($conversation->status->value==='open')<form method="POST" action="{{ route('tenant.admin.ai-conversations.messages.store',$conversation) }}">@csrf<label>Mensaje<input name="message" maxlength="2000" required value="{{ old('message') }}"></label><button class="z-btn" type="submit">Enviar mensaje</button></form>@elseif($conversation->status->value==='human_active'&&(int)$conversation->activeHandoff->assigned_user_id===auth()->id())<form method="POST" action="{{ route('tenant.admin.ai-conversations.human-messages.store',$conversation) }}">@csrf<label>Respuesta humana<input name="message" maxlength="2000" required></label><button class="z-btn">Enviar como humano</button></form><form method="POST" action="{{ route('tenant.admin.ai-handoffs.release',$conversation->activeHandoff) }}">@csrf<button class="z-btn z-btn--ghost">Devolver a IA</button></form>@endif @if($conversation->status->value!=='closed')<form method="POST" action="{{ route('tenant.admin.ai-conversations.close',$conversation) }}">@csrf<button class="z-btn z-btn--ghost" type="submit">Cerrar conversación</button></form>@endif
